// Monta um resumo de documentos por cliente para o painel
public Dictionary<string, ResumoDocumentosDto> MontarResumo(List<Documento> documentos)
{
    var resumo = documentos
        .Where(d => !d.Excluido)
        .GroupBy(d => d.ClienteId)
        .ToDictionary(
            grupo => grupo.Key,
            grupo => new ResumoDocumentosDto
            {
                Total = grupo.Count(),
                Pendentes = grupo.Count(d => d.Status == "PendenteAssinatura"),
                UltimoEnvio = grupo.Max(d => d.DataEnvio)
            });

    return resumo;
}

