@Component({ selector: 'app-conversa', templateUrl: './conversa.component.html' })
export class ConversaComponent implements OnInit {
  mensagens: MensagemDto[] = [];

  constructor(private chatService: ChatService) {}

  // Escuta as mensagens novas do hub e adiciona na lista
  ngOnInit(): void {
    this.chatService.mensagemRecebida$.subscribe(mensagem => {
      console.log('nova mensagem', mensagem.id);
      this.mensagens.push(mensagem);
    });
  }
}

// Atualiza o cliente com os dados recebidos da tela
public async Task AtualizarCliente(ClienteDto dto)
{
    var cliente = new Cliente
    {
        Id = dto.Id,
        Telefone = dto.Telefone,
        Nome = dto.Nome,
        Cpf = dto.Cpf
    };

    await _collection.ReplaceOneAsync(c => c.Id == dto.Id, cliente);
}

// Texto do status exibido no card do processo
public string ObterTextoStatus(Processo? processo)
{
    var nomeCliente = processo?.Cliente?.Nome ?? "Sem cliente";

    return processo?.Status switch
    {
        "Ativo" => $"Em andamento — {nomeCliente}",
        "Arquivado" => "Arquivado",
        null => "Processo não encontrado",
        _ => $"Status desconhecido ({processo.Status})"
    };
}
